package org.freecad.mobilelab;
import org.json.*;import java.io.*;import java.nio.file.*;import java.util.zip.*;
public final class FormatRegression {
 static int checks;interface Action{void run()throws Exception;}static void check(boolean b,String s){if(!b)throw new AssertionError(s);checks++;}static void near(double a,double b){check(Math.abs(a-b)<1e-4,"Expected "+b+" got "+a);}static void reject(Action a)throws Exception{try{a.run();}catch(Exception e){checks++;return;}throw new AssertionError("Invalid interchange accepted");}static JSONObject obj(int id)throws Exception{JSONArray a=new JSONArray(NativeCad.objects());for(int i=0;i<a.length();i++)if(a.getJSONObject(i).getInt("id")==id)return a.getJSONObject(i);throw new AssertionError("missing");}
 public static void main(String[] args)throws Exception{File root=new File(args.length>0?args[0]:Files.createTempDirectory("mesh-formats-").toString());root.mkdirs();NativeCad.clear();ProjectStore.reset();int box=NativeCad.create("Box",new double[]{20,10,4});File stl=new File(root,"box.stl"),glb=new File(root,"box.glb"),mf=new File(root,"box.3mf"),back=new File(root,"back.stl");NativeCad.write(stl.getAbsolutePath(),"stl",box);MeshFormats.glb(stl,glb);MeshFormats.threeMF(stl,mf);
  for(String format:new String[]{"glb","3mf"}){if(format.equals("glb"))MeshFormats.readGlb(glb,back);else MeshFormats.read3mf(mf,back);int mesh=NativeCad.read(back.getAbsolutePath(),"stl");JSONArray b=obj(mesh).getJSONArray("bounds");near(b.getDouble(0),20);near(b.getDouble(1),10);near(b.getDouble(2),4);JSONObject a=new JSONObject(NativeCad.analyze(mesh,3));near(a.getDouble("volume"),800);check(a.getBoolean("watertightMesh"),"Mesh format lost watertight topology: "+format);NativeCad.remove(mesh);}
  try(ZipFile z=new ZipFile(mf)){check(z.size()==3,"3MF OPC parts absent");try(InputStream in=z.getInputStream(z.getEntry("3D/3dmodel.model"));ByteArrayOutputStream out=new ByteArrayOutputStream()){ArchiveIO.copy(in,out,100000,null);String xml=new String(out.toByteArray(),"UTF-8");check(xml.contains("unit=\"millimeter\""),"3MF units missing");int vertices=xml.split("<vertex ").length-1;check(vertices==8,"3MF cube vertex welding failed: "+vertices);}}
  try(RandomAccessFile f=new RandomAccessFile(glb,"rw")){f.seek(8);f.writeInt(0);}reject(()->MeshFormats.readGlb(glb,back));MeshFormats.glb(stl,glb);File evil=new File(root,"evil.3mf");try(ZipOutputStream z=new ZipOutputStream(new FileOutputStream(evil))){MeshFormats.zipText(z,"3D/3dmodel.model","<?xml version=\"1.0\"?><!DOCTYPE model [<!ENTITY boom SYSTEM \"file:///untrusted\">]><model xmlns=\""+MeshFormats.NS+"\">&boom;</model>");}reject(()->MeshFormats.read3mf(evil,back));File unknown=new File(root,"unknown.3mf");try(ZipOutputStream z=new ZipOutputStream(new FileOutputStream(unknown))){MeshFormats.zipText(z,"3D/3dmodel.model","<model unit=\"parsec\" xmlns=\""+MeshFormats.NS+"\"/>");}reject(()->MeshFormats.read3mf(unknown,back));
  File dxf=new File(root,"profile.dxf");Files.write(dxf.toPath(),("0\nSECTION\n2\nHEADER\n9\n$INSUNITS\n70\n4\n0\nENDSEC\n0\nSECTION\n2\nENTITIES\n0\nLINE\n10\n0\n20\n0\n11\n10\n21\n0\n0\nARC\n10\n0\n20\n0\n40\n5\n50\n0\n51\n90\n0\nCIRCLE\n10\n20\n20\n0\n40\n2\n0\nENDSEC\n0\nEOF\n").getBytes("UTF-8"));int drawing=DxfImporter.read(dxf);near(new JSONObject(NativeCad.analyze(drawing,3)).getDouble("length"),10+5*Math.PI/2+4*Math.PI);File lineDxf=new File(root,"line-roundtrip.dxf");int line=NativeCad.curve("Polyline",new double[]{0,0,0,1,5,0,0,1},false,0);NativeCad.write(lineDxf.getAbsolutePath(),"dxf",line);int imported=DxfImporter.read(lineDxf);near(new JSONObject(NativeCad.analyze(imported,3)).getDouble("length"),5);File bad=new File(root,"unitless.dxf");Files.write(bad.toPath(),"0\nSECTION\n2\nENTITIES\n0\nENDSEC\n0\nEOF\n".getBytes("UTF-8"));reject(()->DxfImporter.read(bad));
  check(PrintPrep.check(obj(box),new double[]{30,20,10},1).getBoolean("currentFits"),"Print envelope rejected fitting box");check(!PrintPrep.check(obj(box),new double[]{10,30,20},1).getBoolean("currentFits"),"Envelope accepted wrong orientation");check(PrintPrep.check(obj(box),new double[]{10,30,20},1).getJSONArray("fittingAxisPermutations").length()>0,"No axis permutations found");NativeCad.move(box,7,4,8);PrintPrep.placeOnBed(box);JSONArray bbox=obj(box).getJSONArray("bbox");near(bbox.getDouble(2),0);near(bbox.getDouble(0)+bbox.getDouble(3),0);near(bbox.getDouble(1)+bbox.getDouble(4),0);JSONObject thickness=new JSONObject(NativeCad.thickness(box,5));near(thickness.getDouble("minSampled"),4);check(thickness.getInt("belowThreshold")>0,"Thin wall samples absent");int sphere=NativeCad.create("Sphere",new double[]{5});JSONObject sphereT=new JSONObject(NativeCad.thickness(sphere,1));check(sphereT.getDouble("minSampled")>9.9,"Curved-surface chord caused false thin-wall result");reject(()->NativeCad.thickness(drawing,.6));
  System.out.println("PASS: "+checks+" format/fabrication assertions: 3MF/GLB units and oriented volume/topology round trips, OPC parts/shared vertices, malformed/DTD rejection, exact DXF curves, print placement/envelopes and sampled CAD thickness");System.out.println("Independent reader fixtures: "+root.getAbsolutePath());
 }
}
